M=[[8,8,6],[6,3,6],[6,8,8]]
# Mirror-tile a 3x3 source in a 3x3 arrangement, keeping source central.
rows=[]
for br in range(3):
    tile_rows=M if br==1 else M[::-1]
    for ri in range(3):
        row=[]
        for bc in range(3):
            tile=tile_rows if bc==1 else [r[::-1] for r in tile_rows]
            row.extend(tile[ri])
        rows.append(row)
for r in rows: print(r)
